async page => {
  const check=(ok,message)=>{if(!ok)throw new Error(message)};
  await page.context().grantPermissions(['clipboard-read','clipboard-write'],{origin:'http://127.0.0.1:4173'});
  await page.getByRole('button',{name:'Markdown',exact:true}).click();
  await page.getByRole('button',{name:'复制代码',exact:true}).first().click();
  const clipboard=await page.evaluate(()=>navigator.clipboard.readText());
  check(clipboard.startsWith('async function handleCallback(event: PaymentEvent) {\n  const saved = await events.insertIfAbsent(event.id);'),'Copied code lost original whitespace or included markup');
  check(await page.locator('.hljs-keyword').count()>0,'Syntax highlighting missing');
  const alignment=await page.evaluate(()=>{const u=document.querySelector('.user-bubble').getBoundingClientRect(),a=document.querySelector('.chat-assistant').getBoundingClientRect();return {userRight:u.right,assistantRight:a.right,userLeft:u.left,assistantLeft:a.left}});
  check(Math.abs(alignment.userRight-alignment.assistantRight)<2&&alignment.userLeft>alignment.assistantLeft+30,'User turn not aligned to right of reading column');
  await page.getByRole('button',{name:'补充问题',exact:true}).click();
  check(await page.getByRole('radio',{checked:true}).count()===0,'An answer was silently selected');
  await page.getByRole('button',{name:'下一题',exact:true}).click();
  check(await page.getByRole('alert').isVisible(),'Blank answer allowed');
  await page.getByRole('radio',{name:'custom',exact:false}).check();
  check(await page.getByRole('textbox',{name:'这次希望我推进到哪一步？',exact:true}).count()===0,'A literal custom option collided with free-text mode');
  await page.getByRole('button',{name:'下一题',exact:true}).click();
  await page.getByRole('textbox',{name:'还有哪些边界情况需要关注？',exact:true}).fill('literal label test');
  await page.getByRole('button',{name:'提交回答',exact:true}).click();
  await page.getByLabel('提交结果').waitFor();
  check(JSON.parse(await page.getByLabel('提交结果').innerText()).answers.scope==='custom','Literal custom option was not submitted');
  await page.getByRole('button',{name:'Markdown',exact:true}).click();
  await page.getByRole('button',{name:'补充问题',exact:true}).click();
  await page.getByRole('radio',{name:'实现并验证（推荐）',exact:false}).check();
  await page.getByText('补充说明（可选）',{exact:true}).click();
  await page.getByRole('textbox',{name:'补充说明',exact:true}).fill('请保留现有数据');
  await page.getByRole('button',{name:'下一题',exact:true}).click();
  await page.getByRole('textbox',{name:'还有哪些边界情况需要关注？',exact:true}).fill('重复请求\n并发失败');
  await page.getByRole('button',{name:'上一题',exact:true}).click();
  check(await page.getByRole('textbox',{name:'补充说明',exact:true}).inputValue()==='请保留现有数据','Back navigation discarded answer');
  await page.getByRole('button',{name:'下一题',exact:true}).click();
  await page.getByRole('checkbox',{name:'模拟提交失败',exact:true}).check();
  await page.getByRole('button',{name:'提交回答',exact:true}).click();
  await page.getByRole('alert').filter({hasText:'连接暂时中断'}).waitFor();
  check(await page.getByRole('textbox',{name:'还有哪些边界情况需要关注？',exact:true}).inputValue()==='重复请求\n并发失败','Failed submit discarded input');
  await page.getByRole('checkbox',{name:'模拟提交失败',exact:true}).uncheck();
  await page.getByRole('button',{name:'提交回答',exact:true}).click();
  await page.getByLabel('提交结果').waitFor();
  let result=JSON.parse(await page.getByLabel('提交结果').innerText());
  check(result.answers.scope==='实现并验证（推荐）\n\n请保留现有数据'&&result.answers.detail==='重复请求\n并发失败','Answer payload mismatch');
  await page.getByRole('button',{name:'Markdown',exact:true}).click();
  await page.getByRole('button',{name:'补充问题',exact:true}).click();
  await page.getByRole('radio',{name:'自行填写',exact:false}).check();
  await page.getByRole('textbox',{name:'这次希望我推进到哪一步？',exact:true}).fill('先调查性能瓶颈');
  await page.getByRole('button',{name:'下一题',exact:true}).click();
  await page.getByRole('textbox',{name:'还有哪些边界情况需要关注？',exact:true}).fill('只做只读检查');
  await page.getByRole('button',{name:'提交回答',exact:true}).click();
  await page.getByLabel('提交结果').waitFor();
  result=JSON.parse(await page.getByLabel('提交结果').innerText());check(result.answers.scope==='先调查性能瓶颈','Free-form choice lost');
  await page.getByRole('button',{name:'敏感输入',exact:true}).click();
  const secret=page.getByLabel('输入测试用临时口令',{exact:true});
  check(await secret.getAttribute('type')==='password','Sensitive input not masked');
  await secret.fill('temporary-fixture');await page.getByRole('button',{name:'显示敏感信息',exact:true}).click();
  check(await secret.getAttribute('type')==='text','Show sensitive input failed');
  await page.getByRole('button',{name:'工具授权',exact:true}).click();
  await page.getByRole('button',{name:'拒绝',exact:true}).click();await page.getByLabel('提交结果').waitFor();
  check(JSON.parse(await page.getByLabel('提交结果').innerText()).decision==='decline','Permission decline not sent');
  await page.getByRole('button',{name:'长对话',exact:true}).click();
  await page.locator('.conversation-flow').evaluate(el=>{el.parentElement.scrollTop=100});
  await page.getByRole('button',{name:'回到最新',exact:true}).waitFor();
  const before=await page.locator('.conversation-flow').evaluate(el=>el.parentElement.scrollTop);
  await page.getByRole('button',{name:'追加输出',exact:true}).click();
  const after=await page.locator('.conversation-flow').evaluate(el=>el.parentElement.scrollTop);
  check(Math.abs(before-after)<3,'Streaming interrupted reading history');
  await page.getByRole('button',{name:'回到最新',exact:true}).click();
  check(await page.locator('.conversation-flow').evaluate(el=>{const p=el.parentElement;return p.scrollHeight-p.scrollTop-p.clientHeight<5}),'Return to latest failed');
  return {clipboard:true,markdown:true,customLabel:true,userAlignment:true,questions:true,blankValidation:true,backNavigation:true,failedRetry:true,freeText:true,secretMask:true,decline:true,readingPosition:true};
}
